function wxKind(icon, night){
  const i = +icon;
  if (i === 1 || i === 2) return 'sun';
  if (i >= 3 && i <= 5) return 'partsun';
  if ([6,7,8,38].includes(i)) return 'cloud';
  if (i === 11) return 'fog';
  if ([12,18,26].includes(i)) return 'rain';
  if ([13,14,39,40].includes(i)) return 'showers';
  if ([15,16,17,41,42].includes(i)) return 'storm';
  if ([19,20,21,22,23,24,43,44].includes(i)) return 'snow';
  if ([25,29].includes(i)) return 'sleet';
  if (i === 30) return 'hot'; if (i === 31) return 'cold'; if (i === 32) return 'wind';
  if (i === 33 || i === 34) return 'moon';
  if (i >= 35 && i <= 37) return 'partmoon';
  return night ? 'moon' : 'partsun';
}
