const pad = n => String(n).padStart(2,'0');
const ymd = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const hm = d => `${pad(d.getHours())}:${pad(d.getMinutes())}`;
const parseYMD = s => { const [y,m,d] = String(s).split('-').map(Number); return new Date(y,(m||1)-1,d||1); };
const at = (date, time) => { const d = parseYMD(date); if (time) { const [h,m] = String(time).split(':').map(Number); d.setHours(h||0, m||0, 0, 0); } return d; };
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate()+n); return x; };
const addMin = (d, n) => new Date(d.getTime() + n*60000);
const startOfDay = d => { const x = new Date(d); x.setHours(0,0,0,0); return x; };
const sameDay = (a,b) => a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate();
const isoDow = d => (d.getDay()+6)%7+1;
const startOfWeek = (d, ws=1) => { const x = startOfDay(d); const diff = (x.getDay() - (ws%7) + 7) % 7; return addDays(x, -diff); };
const isoWeek = d => { const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate())); const day = t.getUTCDay()||7; t.setUTCDate(t.getUTCDate()+4-day); const y0 = new Date(Date.UTC(t.getUTCFullYear(),0,1)); return Math.ceil(((t - y0)/86400000 + 1)/7); };
const minutesOf = t => { const [h,m] = String(t||'0:0').split(':').map(Number); return (h||0)*60+(m||0); };
const toHM = mins => { mins = ((Math.round(mins) % 1440) + 1440) % 1440; return `${pad(Math.floor(mins/60))}:${pad(mins%60)}`; };
const DE = 'de-DE';
const fmtWD = (d, f='long') => d.toLocaleDateString(DE, {weekday:f});
const fmtDM = d => d.toLocaleDateString(DE, {day:'numeric', month:'long'});
const fmtLong = d => d.toLocaleDateString(DE, {weekday:'long', day:'numeric', month:'long', year:'numeric'});
const fmtShort = d => d.toLocaleDateString(DE, {weekday:'short', day:'2-digit', month:'2-digit'});
const MONTHS = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const WD_SHORT = ['Mo','Di','Mi','Do','Fr','Sa','So'];
const WD_LONG = ['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'];
function dur(mins){ mins = Math.round(mins); if (mins < 60) return `${mins} min`; const h = Math.floor(mins/60), m = mins%60; return m ? `${h} h ${m} min` : `${h} h`; }
function relTime(target, now = new Date()){
  const diff = target - now, m = Math.round(Math.abs(diff)/60000);
  if (m < 1) return 'jetzt';
  let s;
  if (m < 60) s = `${m} min`;
  else if (m < 1440) { const h = Math.floor(m/60), mm = m%60; s = mm && h < 6 ? `${h} h ${mm} min` : `${Math.round(m/60)} h`; }
  else { const dd = Math.round(m/1440); s = dd === 1 ? '1 Tag' : `${dd} Tagen`; }
  return diff >= 0 ? `in ${s}` : `vor ${s}`;
}
function dayLabel(d, now = new Date()){
  const n = Math.round((startOfDay(d) - startOfDay(now))/86400000);
  if (n === 0) return 'Heute'; if (n === 1) return 'Morgen'; if (n === -1) return 'Gestern'; if (n === 2) return 'Übermorgen';
  return fmtShort(d);
}
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => Math.random().toString(36).slice(2,8) + Date.now().toString(36).slice(-4);
const safeUrl = u => { const s = String(u||'').trim(); if (!s) return ''; if (/^(https?:|discord:)/i.test(s)) return s; if (/^[\w.-]+\.[a-z]{2,}/i.test(s)) return 'https://' + s; return ''; };
const hostOf = u => { try { return new URL(u).host.replace(/^www\./,''); } catch { return u; } };
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

