    const nm = o.kind === 'birthday' ? 'Geburtstag' : o.kind === 'deadline' ? this.dl(o.cat) : this.name(o.cat);
    const M = this.MASK, ref = new Proxy(o.ref, {get: (t, k) => M.has(k) && typeof t[k] === 'string' ? (k === 'title' || k === 'short' || k === 'name' ? nm : '') : t[k]});
