  for (const o of its) { const m = o.allDay ? 90 : o.kind === 'deadline' ? 60 : Math.max(15, (o.end - o.start)/60000 + (o.bb||0) + (o.ba||0)); w[o.cat.color] = (w[o.cat.color]||0) + m; total += m; }
