    if (e.location || (pl && !pl.home)) L.push(`LOCATION:${icsEsc(e.location || pl.name)}`);
    if (e.notes || e.link) L.push(`DESCRIPTION:${icsEsc([e.notes, e.link].filter(Boolean).join('\n'))}`);
    if (!e.allDay) L.push(...alarms([...(Array.isArray(e.reminders) ? e.reminders : state.settings.reminders.event), ...goAlarm(pl)], e.title));
    L.push('END:VEVENT');
