  if (!E.from) { box.innerHTML = E.fromP && E.fromP.home ? `<span class="rlab">Wo wohnst du? Einmal eintragen, dann rechnet alles automatisch.</span>${twSearchBox('home', '')}` : `<span class="muted" style="font-size:13.5px">Für ${esc(E.fromP ? E.fromP.name : 'den Start')} fehlt die Adresse.</span>`; leaveUpdate(f); return; }
