    const o = { title: fd.get('title').trim(), date: fd.get('date'), time: fd.get('time') || '23:59', catId: fd.get('catId'), courseId: fd.get('courseId'), priority: +fd.get('priority') || 2, subtasks: subs, reminders: readRems(fd), link: fd.get('link').trim(), notes: fd.get('notes'), done: !!fd.get('done'), effort: Math.max(0, +fd.get('effort') || 0), exam: !!fd.get('exam') };
