  category(form, fd){ upsert('categories', sheet.ctx.id, {name: fd.get('name').trim(), color: fd.get('color') || fd.get('colorCustom'), symbol: fd.get('symbol') || 'kreis', placeId: fd.get('placeId') || ''}); closeSheet(); commit(); },
