  tripAutoUndo(){ const k = ui._tripAutoKey; if (!k) return; Transit.clearOver(k); delete Transit.cache[k]; invalidate(); toast('Wieder die geplante Verbindung', ''); Transit.refresh(true).then(() => renderSoft()).catch(() => renderSoft()); },
  sleepDetectOn(){ state.settings.sleep.detect = true; commit(); SleepAuto.run(true); render(); },
  sleepDetectNow(){ const n = SleepAuto.run(true); render(); const st = SleepAuto.stat; const w = SleepAuto.why[ymd(new Date())]; toast(n ? `${n} ${n === 1 ? 'Nacht' : 'Nächte'} erkannt` : 'Nichts Neues', n ? 'Im Protokoll unter „vom Handy erkannt“.' : st && !st.ev ? 'Android liefert noch keine Bildschirmzeiten.' : w ? `Letzte Nacht: ${w}` : 'Alle Nächte der letzten Tage sind schon eingetragen.'); },
  sleepDetectOff(){ state.settings.sleep.detect = false; commit(); toast('Erkennung aus', 'Du kannst sie in den Einstellungen unter Schlaf wieder einschalten.'); },
