  sleepPick(el){ const f = el.closest('form'), grp = el.parentElement, inp = f.elements[el.dataset.k], guess = grp.classList.contains('g'), on = el.getAttribute('aria-pressed') === 'true' && !guess; inp.value = on ? '' : el.dataset.v; grp.querySelectorAll('button').forEach(b => b.setAttribute('aria-pressed', !on && b === el)); if (f.classList.contains('sl3-form')) sleepFormTouch(f, grp); },
