  chatAdd(el){ const m = ui.chat[+el.dataset.i]; if (!m || !m.cand || m.added) return; pushUndo(); chatAddCand(m.cand); m.added = true; if (!sheet.el.hidden) closeSheet(); toast('Eingetragen', m.cand.title, undoOpt); commit(); },
  chatMove(el){ const m = ui.chat[+el.dataset.i]; if (!m || !m.cand || !m.suggest) return; const c = m.cand, len = minutesOf(c.end) - minutesOf(c.start), st = new Date(m.suggest); c.date = ymd(st); c.start = hm(st); c.end = toHM(minutesOf(c.start) + (len > 0 ? len : 60)); m.find = analyze(c); m.suggest = null; if (!sheet.el.hidden) EDITORS.add('', +el.dataset.i); else render(); },
