    if (c.kind === 'deadline') { EDITORS.deadline(null, {date:c.date}); const f = sheet.card.querySelector('form'); if (f) { f.elements.title.value = c.title; if (c.start) f.elements.time.value = c.start; if (c.catId) f.elements.catId.value = c.catId; } }
