  pickSubj(el){ const f = el.closest('form'); f.elements.title.value = el.dataset.n; if (f.elements.short && !f.elements.short.value) f.elements.short.value = el.dataset.n; f.elements.color.value = el.dataset.c; const r = f.querySelector(`input[name=symbol][value="${el.dataset.s}"]`); if (r) r.checked = true;
    f.querySelectorAll('[data-act=pickSubj]').forEach(b => b.setAttribute('aria-pressed', b === el)); f.querySelectorAll('[data-act=pickCourseColor]').forEach(b => b.setAttribute('aria-pressed', b.dataset.c === el.dataset.c)); },
  pickCourseColor(el){ const f = el.closest('form'); f.elements.color.value = el.dataset.c; f.querySelectorAll('[data-act=pickCourseColor]').forEach(b => b.setAttribute('aria-pressed', b === el)); },
  editDefaultRem(el){ EDITORS.defaultRem(el.dataset.k); },
