  fitAuto(el){ SleepFit.setManual(el.dataset.k, false); SleepFit.apply(true); commit(); render(); toast('Wieder automatisch', FIT_KEYS[el.dataset.k].l + ' wird aus deinen Nächten eingeschätzt.', {ttl: 3500}); },
  async vaultOpen(){ const el = document.getElementById('vCode'), v = el ? el.value : ''; if (await Vault.tryCode(v)) { _enCache = {k: null}; render(); toast('Freigeschaltet', '', {ttl: 2500}); if (window.VaultX && !VaultX.data.profile) VaultX.profileSheet(); } else { if (el) { el.value = ''; el.focus(); } toast('Code stimmt nicht', '', {ttl: 2500}); } },
  liveTrip(el){ LiveTrip.open(el.dataset.home ? {home: true} : {date: el.dataset.date, i: el.dataset.i}); },
  async stopInfo(el){
    const d = el.dataset, lat = parseFloat(d.lat), lon = parseFloat(d.lon), has = !isNaN(lat) && !isNaN(lon), name = d.name || 'Haltestelle';
    const kind = /^S\+U\b/.test(name) ? 'S- und U-Bahnhof' : /^S\b/.test(name) ? 'S-Bahnhof' : /^U\b/.test(name) ? 'U-Bahnhof' : 'Haltestelle';
    openSheet(`<div class="detail stop-sheet"><div class="st-bg" data-stbg></div>
      <div class="st-hero noimg" data-hero>
        <div class="st-photo" data-stphoto></div>
        <div class="st-top">${backBtn()}<span></span>${closeBtn()}</div>
        <div class="st-glass"><small>${kind}</small><b>${esc(name.replace(/\s*\((Berlin|Bln)\)$/, '').replace(kind === 'Haltestelle' ? /^$/ : /^(S\+U|S|U)\s+/, ''))}</b><span class="st-lines" data-stlines></span></div>
      </div>
      ${has ? '<div class="tmap small st-map" data-stopmap></div>' : ''}
      ${d.id ? `<div class="deps st-deps" data-deps data-n="8" data-stop="${esc(d.id)}" data-src="${esc(d.src || '')}" data-lat="${has ? lat : ''}" data-lon="${has ? lon : ''}" data-line="" data-name="${esc(name)}"></div>` : ''}
      <small class="st-credit" data-stcredit></small></div>`);
    if (d.id) depsLoadAll().then(() => {
      const box = document.querySelector('[data-stlines]'); if (!box) return;
      const seen = new Set(), badges = [...document.querySelectorAll('.st-deps .lnb')].filter(b => !seen.has(b.textContent) && seen.add(b.textContent)).slice(0, 8);
      box.innerHTML = badges.map(b => b.outerHTML).join('');
      const hero = document.querySelector('[data-hero]');
      if (hero && hero.classList.contains('noimg')) { const cols = badges.map(b => getComputedStyle(b).getPropertyValue('--lc').trim()).filter(Boolean); if (cols.length) { hero.style.setProperty('--c1', cols[0]); hero.style.setProperty('--c2', cols[1] || cols[0]); document.querySelector('[data-stbg]').style.setProperty('--c1', cols[0]); } }
    });
    if (has) {
      const mapEl = document.querySelector('[data-stopmap]'); if (mapEl) tripMap(mapEl, null, {point: [lat, lon], fitMe: false});
      const r = await StopImg.get(lat, lon, name);
      const hero = document.querySelector('[data-hero]'), bg = document.querySelector('[data-stbg]'), ph = document.querySelector('[data-stphoto]');
      if (r && hero && ph) {
        const im = new Image(); im.onload = () => {
          const u = `url("${r.src.replace(/"/g, '%22')}")`;
          ph.style.backgroundImage = u; if (bg) { bg.style.backgroundImage = u; bg.classList.add('img'); }
          hero.classList.remove('noimg'); hero.classList.add('img');
          const c = document.querySelector('[data-stcredit]'); if (c) c.textContent = `Foto: ${r.title} · Wikipedia`;
        }; im.src = r.src;
      }
    }
  },
  sleepInfo(el){ DETAIL.sleep(el.dataset.date); },
  closeSheet(){ closeSheet(); },
  deleteItem(el){
    if (!armConfirm(el)) return;
    const {kind, id} = sheet.ctx, item = findItem(kind, id);
    pushUndo();
    state[LISTS[kind]] = state[LISTS[kind]].filter(x => x.id !== id);
    if (kind === 'category') ['events','deadlines','courses','todos'].forEach(k => state[k].forEach(x => { if (x.catId === id) x.catId = ''; }));
    if (kind === 'place') ['events','courses'].forEach(k => state[k].forEach(x => { if (x.placeId === id) x.placeId = ''; }));
    closeSheet(); toast('Gelöscht', item ? (item.title || item.name || item.label || item.text) : '', undoOpt); commit();
  },
  skipOccurrence(el){ const it = findItem(el.dataset.kind, el.dataset.id); if (!it) return; pushUndo(); it.skip = [...new Set([...(it.skip||[]), el.dataset.date])]; closeSheet(); toast('Fällt aus', `${it.short || it.title} am ${fmtShort(parseYMD(el.dataset.date))}`, undoOpt); commit(); },
  unskip(el){ const it = sheet.ctx && findItem(sheet.ctx.kind, sheet.ctx.id); if (!it) return; it.skip = (it.skip||[]).filter(s => s !== el.dataset.date); el.remove(); Store.schedule(); invalidate(); },
  nudge(el){ const e = state.events.find(x => x.id === el.dataset.id); if (!e || e.allDay) return; if (!ui.undo || ui.undo.label !== 'nudge') pushUndo('nudge'); const m = +el.dataset.m, s = at(e.date, e.start), en = at(e.date, e.end); e.date = ymd(addMin(s,m)); e.start = hm(addMin(s,m)); e.end = hm(addMin(en,m)); delete e.ex; commit(); DETAIL.occurrence('event', e.id, e.date); },
  toggleDone(el){ const d = state.deadlines.find(x => x.id === el.dataset.id); if (!d) return; pushUndo(); d.done = !d.done; haptic(); if (d.done) { (d.subtasks||[]).forEach(s => s.done = true); toast('Erledigt', d.title, undoOpt); } if (el.dataset.close) closeSheet(); commit(); },
  toggleSub(el){ const d = state.deadlines.find(x => x.id === el.dataset.id), s = d && d.subtasks.find(x => x.id === el.dataset.sid); if (!s) return; s.done = el.checked; Store.schedule(); invalidate(); render(); },
  toggleTodo(el){ const t = state.todos.find(x => x.id === el.dataset.id); if (!t) return; t.done = !t.done; haptic(); commit(); },
  clearTodos(){ state.todos = state.todos.filter(t => !t.done); commit(); },
