  remGo(el){
    const v = +el.value, T = state.settings.travel, cur = new Set(Array.isArray(T.remindAt) ? T.remindAt : [10]);
    if (el.checked) cur.add(v); else cur.delete(v);
    if (!cur.size) { el.checked = true; toast('Mindestens eine Zeit', ''); return; }
    T.remindAt = [...cur].sort((a, b) => b - a); commit(); if (typeof Push !== 'undefined') Push.queue();
  },
