    state.categories.forEach(c => { if (c.placeId && !placeById(c.placeId)) c.placeId = ''; });
    ['events','courses'].forEach(k => state[k].forEach(x => { if (x.placeId && !placeById(x.placeId)) x.placeId = ''; }));
    if (state.semester.ex) state.semester = {name:'', start:'', end:'', breaks:[]};
