  if (ib != null && (ib > b || b - ib > 300)) ib = null;
  const waso = x.waso != null && x.waso !== '' ? +x.waso || 0 : null;
  const dur = Math.max(0, w - b - (waso || 0)), tib = ib != null ? w - ib : null;
  return {b, w, dur, mid: b + (w - b) / 2, ib, tib, solEst: !!x.bedRaw && (x.lat == null || x.lat === ''), sol: ib != null ? b - ib : null, waso, se: tib ? Math.max(0, Math.min(100, Math.round(dur / tib * 100))) : null};
