const sAvg = a => a.length ? a.reduce((p, c) => p + c, 0) / a.length : null;
const sMed = a => { if (!a.length) return null; const s = a.slice().sort((x, y) => x - y), k = s.length >> 1; return s.length % 2 ? s[k] : (s[k - 1] + s[k]) / 2; };
