  out.trend = cur.length >= 3 && prev.length >= 3 ? {dur: sAvg(cur.map(n => n.dur)) - sAvg(prev.map(n => n.dur)), on: sAvg(cur.map(n => n.b)) - sAvg(prev.map(n => n.b)), q: cur.filter(n => n.q).length >= 3 && prev.filter(n => n.q).length >= 3 ? sAvg(cur.filter(n => n.q).map(n => n.q)) - sAvg(prev.filter(n => n.q).map(n => n.q)) : 0} : null;
