const planOf = c => PLANS[c && c.plan] ? c.plan : 'uni';
const PS = () => { const p = (state.plans = state.plans || {}); if (!Array.isArray(p.active) || !p.active.length) p.active = ['uni']; p.terms = p.terms || {}; if (!PLANS[p.cur] || !p.active.includes(p.cur)) p.cur = p.active[0]; return p; };
const termOf = id => id === 'uni' ? state.semester : (PS().terms[id] = PS().terms[id] || {name: '', start: '', end: '', breaks: []});
function termRange(id){ const s = termOf(id); if (!s || !s.start || !s.end) return null; return {start: parseYMD(s.start), end: addDays(parseYMD(s.end), 1)}; }
function inBreakP(d, id){ const s = ymd(d); return (termOf(id).breaks || []).some(b => b.start && b.end && s >= b.start && s <= b.end); }
function ctypeOf(c){ const P = PLANS[planOf(c)]; return (P.types && P.types[c.type]) || COURSE_TYPES[c.type] || c.type || ''; }
function ensurePlanCat(id){ const d = PLANS[id].cat; let c = state.categories.find(x => x.id === d.id); if (!c) { c = {...d}; state.categories.push(c); } return c.id; }
function courseCat(c){ const cat = catById(c.catId); return c.color || c.symbol ? {...cat, color: c.color || cat.color, symbol: c.symbol || cat.symbol} : cat; }

/* Raster für einen Plan: Zeilen = Zeitblöcke des Plans */
function ttGridP(days, id){
  const P = PLANS[id], S = P.slots.filter(s => minutesOf(s[1]) - minutesOf(s[0]) <= 240), td = isoDow(new Date());
  const list = state.courses.filter(c => planOf(c) === id);
  let html = `<div class="tt-grid" style="--days:${days}"><div></div>`;
  for (let d = 1; d <= days; d++) html += `<div class="tt-head${d === td ? ' today' : ''}">${WD_LONG[d - 1]}</div>`;
  S.forEach((sl, i) => { html += `<div class="tt-slot" style="grid-row:${i + 2};grid-column:1"><b>${esc(P.lab(sl, i))}</b>${sl[0]}</div>`; });
  for (let d = 1; d <= days; d++) {
    const taken = new Set(), by = {};
    list.filter(c => +c.day === d).forEach(c => { let i = S.findIndex(s => minutesOf(s[1]) > minutesOf(c.start)); if (i < 0) i = S.length - 1; let j = i; while (j + 1 < S.length && minutesOf(S[j + 1][0]) < minutesOf(c.end)) j++; (by[i] = by[i] || []).push({c, sp: j - i + 1}); });
    for (const [i, L] of Object.entries(by)) {
      const sp = Math.max(...L.map(x => x.sp)); for (let k = 0; k < sp; k++) taken.add(+i + k);
      html += `<div class="tt-cell" style="grid-row:${+i + 2} / span ${sp};grid-column:${d + 1}">${L.map(({c}) => { const cat = courseCat(c); return `<button class="tt-block" style="--c:${cat.color}" data-act="edit" data-kind="course" data-id="${c.id}"><span class="ty">${esc(ctypeOf(c))}${c.weeks !== 'all' ? (c.weeks === 'odd' ? ' · ungerade KW' : ' · gerade KW') : ''}</span><b>${esc(PV(c.short || c.title, cat))}</b><small>${esc(c.start)}–${esc(c.end)}${c.room ? ' · ' + esc(c.room) : ''}</small><span class="wm" aria-hidden="true">${sy(cat.symbol)}</span></button>`; }).join('')}</div>`;
    }
    for (let i = 0; i < S.length; i++) if (!taken.has(i)) html += `<button class="tt-cell free" style="grid-row:${i + 2};grid-column:${d + 1}" data-act="newCourseAt" data-day="${d}" data-slot="${i}" aria-label="${esc(P.item)} am ${WD_LONG[d - 1]} anlegen">${ic('plus', 's')}</button>`;
  }
  return html + '</div>';
}

/* Ansicht Stundenplan */
function planView(){
  const PSx = PS(), id = PSx.cur, P = PLANS[id], now = new Date(), sem = termOf(id), sr = termRange(id);
  let prog = '';
  if (sr) { const total = sr.end - sr.start, pct = Math.round(clamp(now - sr.start, 0, total) / total * 100), wl = Math.max(0, Math.ceil((sr.end - now) / (7 * 86400000)));
    prog = `<div class="semprog"><div class="track"><i style="width:${pct}%"></i></div><div class="lbl"><span class="num">${parseYMD(sem.start).toLocaleDateString(DE)}</span><span>${now < sr.start ? 'beginnt bald' : now >= sr.end ? 'beendet' : `noch ${wl} Wochen`}</span><span class="num">${parseYMD(sem.end).toLocaleDateString(DE)}</span></div></div>`; }
  const mine = state.courses.filter(c => planOf(c) === id), days = mine.some(c => +c.day === 6) ? 6 : 5;
  const courses = [...mine].sort((a, b) => a.day - b.day || minutesOf(a.start) - minutesOf(b.start));
  const tabs = `<div class="pl-tabs">${PSx.active.map(k => `<button class="chip pl-tab" data-act="planGo" data-p="${k}" aria-pressed="${k === id}">${ic(PLANS[k].ic, 's')}${esc(PLANS[k].s)}<em>${state.courses.filter(c => planOf(c) === k).length}</em></button>`).join('')}<button class="chip" data-act="planAdd">${ic('plus', 's')}Plan</button></div>`;
  const nextBreak = (sem.breaks || []).filter(b => b.end >= ymd(now)).sort((a, b) => a.start.localeCompare(b.start))[0];
  return `${tabs}
    ${Bau.kap({ic: P.ic, t: P.term, m: esc(P.l), act: `<button class="btn sm" data-act="editSemester" data-p="${id}">${ic('stift', 's')}Bearbeiten</button>`})}
    <section class="panel"><div class="sem"><div><div class="big">${esc(sem.name || 'Noch nicht festgelegt')}</div>${nextBreak ? `<small class="muted">${esc(nextBreak.label || P.breaks)}: ${esc(fmtShort(parseYMD(nextBreak.start)))}–${esc(fmtShort(parseYMD(nextBreak.end)))}</small>` : ''}</div>${prog || `<span class="muted">Beginn und Ende festlegen, damit ${esc(P.items)} nur in dieser Zeit erscheinen.</span>`}</div></section>
    ${mine.length ? Bau.kap({ic: 'raster', t: 'Wochenplan', m: days === 6 ? 'Mo bis Sa' : 'Mo bis Fr'}) + `<div class="scroller">${ttGridP(days, id)}</div>` : ''}
    ${Bau.kap({ic: P.ic, t: P.items, n: mine.length, act: `${id === 'uni' ? `<button class="btn sm" data-act="importIcsPrompt">${ic('hoch', 's')}ICS</button>` : ''}<button class="btn primary sm" data-act="newCourse">${ic('plus', 's')}${esc(P.item)}</button>`})}
    ${courses.length ? `<div class="cards">${courses.map(c => { const cat = courseCat(c); return `<button class="card" style="--c:${cat.color}" data-act="edit" data-kind="course" data-id="${c.id}"><span class="sym">${sy(cat.symbol)}</span><span style="min-width:0"><b>${esc(PV(c.title, cat))}</b><small>${WD_SHORT[c.day - 1]} <span class="num">${esc(c.start)}–${esc(c.end)}</span> · ${esc(ctypeOf(c))}${c.weeks !== 'all' ? ` · ${c.weeks === 'odd' ? 'ungerade' : 'gerade'} KW` : ''}${c.room ? ' · ' + esc(PV(c.room, cat, '')) : ''}</small></span></button>`; }).join('')}</div>`
      : emptyArt(P.ic === 'buch' ? 'buch' : 'liste', `Noch keine ${P.items}.`, id === 'uni' ? 'Tippe auf einen freien Block oder importiere den Stundenplan als ICS aus MOSES.' : `Tippe oben auf „${P.item}“ oder auf einen freien Block im Wochenplan.`)}
    ${id === 'uni' && typeof Sens !== 'undefined' && Sens.on() ? lectureTile() : ''}
`;
}
