    if (Loc.on()) Loc.sync(true);
    openSheet(`<div class="detail live">${backBtn()}${head('Unterwegs')}<div class="lt-eta" data-lteta><span class="muted">Live-Daten werden geladen …</span></div><div class="lt-now" data-ltnow hidden></div><div class="lt-pick" data-ltpick hidden></div><div data-ltpath></div><div class="tmap big" data-livemap></div><div data-ltsteps></div></div>`, {live: true});
