    if (hi < pts.length - 1) h += `<button type="button" class="lp-more" data-act="ltAll">${pts.length - 1 - hi} weitere anzeigen</button>`;
    else if (this._all && lo === 0 && pts.length > 6) h += `<button type="button" class="lp-more" data-act="ltAll">Weniger</button>`;
