Object.assign(ACTIONS, { txLeft(){ TRIPX.left(); }, txStop(){ TRIPX.stop(); }, txArr(){ TRIPX.arr(); }, txUndo(){ TRIPX.undo(); } });
/* „Heute“: unterwegs zeigt die Wegkarte mit den drei Knöpfen */
HEUTE.focus = (o => function(items, P){ const c = TRIPX.cur(); return c ? TRIPX.card(c) : o.call(this, items, P); })(HEUTE.focus);
/* Wege ohne Fahrplan: gelernte Zeit einrechnen */
travelMinutes = (o => function(place, when){ const r = o(place, when); if (place && !place.home && !r.route && r.total) { const x = TRIPX.extra(place.id); if (x) return {...r, total: Math.max(1, r.total + x), learned: x}; } return r; })(travelMinutes);
/* Wege nach Fahrplan ohne Live-Daten: gelernte Zeit beim Losgehen einrechnen */
planDay = (o => function(d){ const r = o(d); for (const l of r.legs) { if (l._lx || !l.live || !l.live.plan) continue; l._lx = 1; const x = TRIPX.extra(TRIPX.pid(l)); if (!x) continue;
  if (l.kind === 'go') { l.depart = addMin(l.depart, -x); } else { l.arrive = addMin(l.arrive, x); } l.mins += x; l.learned = x; }
  if (r.legs.length) { const g = r.legs.find(l => l.kind === 'go'); r.firstDepart = g ? g.depart : null; } return r; })(planDay);

function init(){
  sheet.el = document.getElementById('sheet'); sheet.card = document.getElementById('sheetCard');
  document.getElementById('fab').innerHTML = ic('plus');
  const local = Store.loadLocal();
  if (local) state = local; else { state = migrate(exampleState()); Store.fromExample = true; }
  ui.view = 'heute';
  try { const lv = JSON.parse(localStorage.getItem('kal-ui') || 'null'); if (lv && Date.now() - lv.t < 2*3600000 && NAV_IDS.includes(lv.view)) { ui.view = lv.view; if (MODE_ORDER[lv.mode] != null) ui.mode = lv.mode; } } catch {}
  const hs = /^(import|x|t|c)=/.test(location.hash.slice(1)) ? '' : location.hash.slice(1);
  if (LEGACY[hs]) { ui.view = 'kalender'; ui.mode = LEGACY[hs]; } else if (NAV_IDS.includes(hs)) ui.view = hs;
  WX.loadCache();
  MOD.boot(); SHELL.boot();
  applyTheme(); bindEvents(); bindDrag(); bindSwipe(); setSync(); render();
  Reminders.load(); Reminders.last = Date.now();
  setInterval(() => Reminders.check(), 20000);
  BackNav.init();
  if (STANDALONE) { Loc.sync(); document.addEventListener('visibilitychange', () => Loc.sync()); }
  setTimeout(() => { try { migrateWorkCat(); } catch {} }, 1500);
  MOD.ask();
  Vault.boot();
  setTimeout(() => { try { SleepFit.daily(); } catch {} }, 4000);
  Offplan.opened(); document.addEventListener('visibilitychange', () => { if (!document.hidden) Offplan.opened(); });
  setInterval(() => { if (!document.hidden) { try { TrainMatch.tick(); } catch {} try { Offplan.tick(); } catch {} try { Where.paint(); } catch {} } }, 20000);
  setTimeout(() => Isis.auto(), 6000); document.addEventListener('visibilitychange', () => { if (!document.hidden) Isis.auto(); });
  if (Native.has('sense')) { setInterval(() => { if (!document.hidden) TripAuto.tick(); }, 30000); setTimeout(() => TripAuto.tick(), 5000); window.addEventListener('kalresume', () => { TripAuto.tick(); SleepAuto.run(true); }); window.addEventListener('kalperm', () => setTimeout(render, 300)); }
  if (Native.has('sleep')) { setTimeout(() => SleepAuto.run(true), 2500); document.addEventListener('visibilitychange', () => { if (!document.hidden) setTimeout(() => SleepAuto.run(), 600); }); }
  if (Native.on()) { setTimeout(() => Native.sync(true), 1500); setInterval(() => Native.sync(), 5 * 60000); document.addEventListener('visibilitychange', () => { if (document.hidden) Native.sync(); }); }
  setInterval(() => document.querySelectorAll('[data-ago]').forEach(e => { const a = Math.max(0, Math.round((Date.now() - +e.dataset.ago) / 60000)); e.textContent = a ? `vor ${a} min aktualisiert` : 'gerade aktualisiert'; }), 15000);
  if (STANDALONE) { setTimeout(() => Transit.refresh(), 2500); setInterval(() => { if (!document.hidden) Transit.refresh(); }, 30000); document.addEventListener('visibilitychange', () => { if (!document.hidden) Transit.refresh(); }); }
  if (STANDALONE) { setTimeout(() => Push.sync(), 4000); setInterval(() => { if (!document.hidden) Push.sync(); }, 20*60000); document.addEventListener('visibilitychange', () => { if (!document.hidden) Push.queue(); }); }
  let lastMin = new Date().getMinutes(), lastDay = ymd(new Date());
  setInterval(() => {
    const n = new Date();
    if (ymd(n) !== lastDay) { lastDay = ymd(n); invalidate(); }
    applyDaypart();
    if (n.getMinutes() !== lastMin && sheet.el.hidden && !ui.search && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName || '')) {
      lastMin = n.getMinutes(); if (ui.view === 'heute' || ui.view === 'kalender' && ['tag','woche'].includes(ui.mode)) { const y = window.scrollY; render(); window.scrollTo(0, y); } else renderTop();
    }
  }, 15000);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) { Reminders.check(); invalidate(); renderSoft(); } });
  if (STANDALONE) {
    /* Code aus dem Link merken (überlebt das Neuladen beim ersten Besuch), dann aus der Adresse nehmen */
    const m = /^#(t|c|x|import)=(.+)$/i.exec(location.hash);
    if (m) { try { sessionStorage.setItem('kal-xfer', (/^[tc]$/i.test(m[1]) ? 't:' : 'x:') + m[2]); } catch {} try { history.replaceState(null, '', location.pathname + location.search); } catch {} }
    let pend = null; try { pend = sessionStorage.getItem('kal-xfer'); } catch {}
    if (!pend && m) pend = (/^[tc]$/i.test(m[1]) ? 't:' : 'x:') + m[2];
    if (pend) { ui._onbShown = true; setTimeout(() => pend.startsWith('t:') ? importFromToken(pend.slice(2)) : importFromCode(pend.slice(2)), 300); }
  }
  Store.connect();
  WX.start();
}
init();
